import type { EngineInterface, PluginOptions, Register } from 'claude-code'

type Language = 'zh' | 'en' | 'de' | 'ja'
type VoiceChoice = 'alternate' | 'female' | 'male'

type Phrases = {
  edgeVoices: { female: string; male: string }
  macVoices: string[]
  separator: string
  tools: Record<string, string>
  otherTool: (name: string) => string
  permission: (label: string) => string
  question: (text: string) => string
  error: string
  doneFallback: string
  summarySystem: string
  summaryPrompt: (prompt: string, answer: string) => string
}

const PHRASES: Record<Language, Phrases> = {
  zh: {
    edgeVoices: { female: 'zh-CN-XiaoxiaoNeural', male: 'zh-CN-YunxiNeural' },
    macVoices: ['Lilian (Premium)', 'Lili (Premium)', 'Tingting (Premium)', 'Tingting (Enhanced)', 'Tingting'],
    separator: '，',
    tools: { Bash: '跑个命令', Edit: '改个文件', Write: '写个文件', WebFetch: '上网看个网页', WebSearch: '上网搜一下' },
    otherTool: name => `用一下 ${name}`,
    permission: label => `我想${label}，你点个同意呗。`,
    question: text => `问你个事儿：${text}`,
    error: '哎，出了点岔子，你来瞅一眼吧。',
    doneFallback: '活儿干完啦，你来看看吧。',
    summarySystem:
      '你是用户的搭档，刚帮他干完一件活儿。用一句很口语、很随意的中文告诉他干完了什么，不超过二十五个字，不要称呼他，不要引号。例如：登录页那个报错我搞定啦，你来瞅一眼吧。',
    summaryPrompt: (prompt, answer) => `用户的请求：${prompt}\n\n助手的最终回复：${answer}`,
  },
  en: {
    edgeVoices: { female: 'en-US-AvaNeural', male: 'en-US-AndrewNeural' },
    macVoices: ['Ava (Premium)', 'Zoe (Premium)', 'Ava (Enhanced)', 'Samantha (Enhanced)', 'Samantha'],
    separator: ', ',
    tools: {
      Bash: 'run a command',
      Edit: 'edit a file',
      Write: 'write a file',
      WebFetch: 'open a web page',
      WebSearch: 'search the web',
    },
    otherTool: name => `use ${name}`,
    permission: label => `I want to ${label}, mind giving me the okay?`,
    question: text => `quick question: ${text}`,
    error: 'oops, something went wrong, come take a look.',
    doneFallback: 'all done, come take a look.',
    summarySystem:
      "You are the user's teammate and just finished a task for them. In one short, casual spoken English sentence (max 15 words), tell them what you got done. Do not address them by name, no quotes. Example: Fixed that login page error, come check it out.",
    summaryPrompt: (prompt, answer) => `User's request: ${prompt}\n\nAssistant's final reply: ${answer}`,
